use customer_behavior
select * from customer_data;

-- 1. Revenue Analysis 
-- Compared total revenue generated by male and female customers.

SELECT 
    gender, SUM(purchase_amount) AS total_revenue
FROM
    customer_data
GROUP BY gender;

-- 2. Discount & Spending Analysis 
 -- Identified discount users whose purchase amounts were at or above the overall average.

SELECT 
    customer_id, purchase_amount
FROM
    customer_data
WHERE
    discount_applied = 'Yes'
        AND purchase_amount >= (SELECT 
            AVG(purchase_amount)
        FROM
            customer_data);
            
-- 3. Product Rating Analysis 
-- Ranked the top 5 products by average review rating.

SELECT 
    item_purchased,
    ROUND(AVG(review_rating), 2) AS 'Average Product Rating'
FROM
    customer_data
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

-- 4. Shipping Analysis 
-- Compared average purchase amounts for Standard and Express shipping.

SELECT 
    shipping_type, round(avg(purchase_amount),2)
FROM
    customer_data
WHERE
    shipping_type IN ('Standard' , 'Express')
GROUP BY shipping_type;

-- 5. Subscription Analysis 
-- Compared customer counts, average spending, and total revenue between subscribers and non-subscribers.

SELECT 
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount), 2) AS avg_spend,
    ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM
    customer_data
GROUP BY subscription_status
ORDER BY total_revenue , avg_spend DESC;

-- 6. Discount Dependency Analysis 
-- Identified the top 5 products by percentage of purchases with discounts applied.

 SELECT 
    item_purchased,
    ROUND(100.0 * SUM(CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END) / COUNT(*),
            2) AS discount_rate
FROM
    customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- 7. Customer Segmentation 
-- Classified customers into New, Returning, and Loyal segments based on previous purchases.

with customer_type as (
	select customer_id , previous_purchases , 
	case when previous_purchases=1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal' end as customer_segment from customer_data )
SELECT 
    customer_segment, COUNT(*) AS Number_of_Customers
FROM
    customer_type
GROUP BY customer_segment;

-- 8. Product Popularity Analysis 
-- Identified the top 3 most purchased products within each category.

with item_counts as 
( select category , item_purchased , count(customer_id) as total_orders ,
row_number() over (partition by category order by count(customer_id) desc) as item_rank from customer_data group by category , item_purchased)
select item_rank , category , item_purchased , total_orders from item_counts where item_rank <=3;

-- 9. Repeat Buyer Analysis 
-- Compared subscription status among customers with more than 5 previous purchases.
 
SELECT 
    subscription_status, COUNT(customer_id) AS repeated_buyers
FROM
    customer_data
WHERE
    previous_purchases > 5
GROUP BY subscription_status;
 
-- 10.Age Group Revenue Analysis 
-- Compared total revenue across customer age groups.
 
SELECT 
    age_group, SUM(purchase_amount) AS total_revenue
FROM
    customer_data
GROUP BY age_group
ORDER BY total_revenue DESC;




